   output: [2, 8, 14, 18, 25, 26]

   input: [3, 3, 7, 1, -2]
   output: [-2, -1, 6, 9, 12]
*/
void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    int n = x.size();
    if (n == 0) {
        output.clear();
        return;
    }

    output.resize(n);

    // Reverse prefix sum: output[i] = x[i] + x[i+1] + ... + x[n-1]
    // This is equivalent to: compute prefix sum of reversed x, then reverse the result.

    // Step 1: Create a reversed copy of x
    std::vector<int> rev_x(n);
    #pragma omp parallel for
    for (int i = 0; i < n; i++) {
        rev_x[i] = x[n - 1 - i];
    }

    // Step 2: Compute prefix sum of rev_x using a parallel scan (prefix sum)
    std::vector<int> prefix(n);

    // Use a work-efficient parallel prefix sum (Blelloch-style or similar)
    // For simplicity and correctness, we'll use a two-phase approach:
    // Phase 1: Local prefix sums within chunks
    // Phase 2: Global prefix sums using reduction-like approach

    // Actually, let's use a straightforward parallel prefix sum implementation.
    // We'll use the inclusive scan approach with OpenMP.

    // For a correct parallel prefix sum, we can use a tree-based approach.
    // Let's implement a simple work-efficient parallel prefix sum.

    // Phase 1: Up-sweep (reduce) to compute partial sums
    // Phase 2: Down-sweep to compute prefix sums

    // Copy rev_x into prefix
    #pragma omp parallel for
    for (int i = 0; i < n; i++) {
        prefix[i] = rev_x[i];
    }

    // Parallel prefix sum using a tree-based approach
    // This is a simplified version that works for any thread count

    // We'll use a sequential prefix sum for small arrays and parallel for large ones
    // But to ensure correctness under every thread count, let's use a proper parallel scan.

    // Alternative: Use OpenMP's parallel for with a critical section for the accumulator
    // This is not efficient but is correct. However, the problem asks for parallel computation.

    // Let's implement a proper parallel prefix sum using the Blelloch algorithm.

    // For simplicity, I'll use a different approach: compute the total sum first, then use
    // the relationship: reverse_prefix_sum[i] = total_sum - prefix_sum[i-1] (with prefix_sum[-1] = 0)

    // Step 2a: Compute total sum
    int total_sum = 0;
    #pragma omp parallel for reduction(+:total_sum)
    for (int i = 0; i < n; i++) {
        total_sum += x[i];
    }

    // Step 2b: Compute forward prefix sum of x
    std::vector<int> fwd_prefix(n);
    #pragma omp parallel for
    for (int i = 0; i < n; i++) {
        fwd_prefix[i] = x[i];
    }

    // Now compute the forward prefix sum in parallel
    // Use a parallel scan on fwd_prefix

    // For a correct parallel prefix sum, let's use a simple approach with chunks
    int num_threads = omp_get_max_threads();
    std::vector<int> chunk_sums(num_threads, 0);

    // Divide work into chunks
    int chunk_size = (n + num_threads - 1) / num_threads;

    // Compute local prefix sums and chunk sums
    #pragma omp parallel num_threads(num_threads)
    {
        int tid = omp_get_thread_num();
        int start = tid * chunk_size;
        int end = std::min(start + chunk_size, n);

        if (start < n) {
            // Compute local prefix sum for this chunk
            int local_sum = 0;
            for (int i = start; i < end; i++) {
                local_sum += fwd_prefix[i];
                fwd_prefix[i] = local_sum;
            }
            chunk_sums[tid] = local_sum;
        }
    }

    // Compute prefix sum of chunk_sums
    for (int i = 1; i < num_threads; i++) {
        chunk_sums[i] += chunk_sums[i - 1];
    }

    // Add chunk prefix sums to each element
    #pragma omp parallel num_threads(num_threads)
    {
        int tid = omp_get_thread_num();
        int start = tid * chunk_size;
        int end = std::min(start + chunk_size, n);

        if (tid > 0 && start < n) {
            int offset = chunk_sums[tid - 1];
            for (int i = start; i < end; i++) {
                fwd_prefix[i] += offset;
            }
        }
    }

    // Step 3: Compute reverse prefix sum using total_sum and forward prefix sum
    // reverse_prefix_sum[i] = total_sum - (fwd_prefix[i-1] if i > 0 else 0)
    #pragma omp parallel for
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            output[i] = total_sum;
        } else {
            output[i] = total_sum - fwd_prefix[i - 1];
        }
    }
}
